static const struct KantoSeamOrigin *KantoSeam_FindOrigin(const struct MapLayout *layout)
{
    u32 i;
    for (i = 0; i < ARRAY_COUNT(sKantoSeamOrigins); i++)
        if (sKantoSeamOrigins[i].layout == layout)
            return &sKantoSeamOrigins[i];
    return NULL;
}

const struct KantoSeam *KantoSeam_Find(const struct MapLayout *layout)
{
    u32 i;
    for (i = 0; i < ARRAY_COUNT(sKantoSeams); i++)
        if (sKantoSeams[i].layout == layout)
            return &sKantoSeams[i];
    return NULL;
}

bool8 KantoSeam_ChangesPrimaryPalette(const struct MapLayout *layout)
{
    const struct KantoSeam *seam = KantoSeam_Find(layout);
    u32 i;
    if (seam != NULL)
        for (i = 0; i < seam->paletteCount; i++)
            if (seam->palettes[i].destination < GetNumPalsInPrimary(layout) * 16)
                return TRUE;
    return FALSE;
}

const struct KantoSeamMetatile *KantoSeam_GetMetatile(const struct MapLayout *layout, u16 mid)
{
    const struct KantoSeam *seam = KantoSeam_Find(layout);
    if (seam != NULL && mid >= seam->firstMid && mid - seam->firstMid < seam->metatileCount)
    {
        const struct KantoSeamMetatile *entry = &seam->metatiles[mid - seam->firstMid];
        // Explicit NULL slots retain an original live MID between alias ranges.
        return entry->sourceLayout != NULL ? entry : NULL;
    }
    return NULL;
}

u16 KantoSeam_TranslateBlock(const struct MapLayout *target, const struct MapLayout *source, u16 block)
{
    const struct KantoSeam *seam = KantoSeam_Find(target);
    u32 i;
    if (block == MAPGRID_UNDEFINED || source == target)
        return block;
    if (seam != NULL)
        for (i = 0; i < seam->metatileCount; i++)
            if (seam->metatiles[i].sourceLayout == source && seam->metatiles[i].sourceMid == (block & MAPGRID_METATILE_ID_MASK))
                return (block & ~MAPGRID_METATILE_ID_MASK) | (seam->firstMid + i);
    // Only unadapted, source-qualified identity entries reach this path.
    return block;
}

u16 KantoSeam_ReencodeCacheBlock(const struct MapLayout *previous, const struct MapLayout *current, u16 block)
{
    const struct KantoSeamMetatile *entry;
    const struct MapLayout *owner = previous;
    if (block == MAPGRID_UNDEFINED)
        return block;
    entry = KantoSeam_GetMetatile(previous, block & MAPGRID_METATILE_ID_MASK);
    if (entry != NULL)
    {
        owner = entry->sourceLayout;
        block = (block & ~MAPGRID_METATILE_ID_MASK) | entry->sourceMid;
    }
    return KantoSeam_TranslateBlock(current, owner, block);
}

u16 KantoSeam_CanonicalMid(const struct MapLayout *layout, u16 mid)
{
    const struct KantoSeamMetatile *entry = KantoSeam_GetMetatile(layout, mid);
    const struct KantoSeamOrigin *origin = KantoSeam_FindOrigin(layout);
    if (entry != NULL && origin != NULL && mid >= origin->firstMid && mid - origin->firstMid < origin->metatileCount)
        return origin->canonicalMids[mid - origin->firstMid];
    return entry != NULL ? entry->sourceMid : mid;
}

u16 KantoSeam_CutResult(const struct MapLayout *layout, u16 previousMid, u16 result)
{
    const struct KantoSeamMetatile *entry = KantoSeam_GetMetatile(layout, previousMid);
    const struct KantoSeamOrigin *origin = KantoSeam_FindOrigin(layout);
    const struct KantoSeam *seam = KantoSeam_Find(layout);
    u32 i;
    if (entry != NULL && origin != NULL && previousMid >= origin->firstMid && previousMid - origin->firstMid < origin->metatileCount)
    {
        u16 originId = origin->originIds[previousMid - origin->firstMid];
        for (i = 0; i < origin->metatileCount; i++)
            if (originId != 0 && origin->originIds[i] == originId && origin->canonicalMids[i] == result
                && seam->metatiles[i].sourceLayout == entry->sourceLayout)
                return seam->firstMid + i;
    }
    return entry != NULL ? KantoSeam_TranslateBlock(layout, entry->sourceLayout, result) : result;
}

void KantoSeam_LoadResources(const struct MapLayout *layout, bool8 skipFaded)
{
    const struct KantoSeam *seam = KantoSeam_Find(layout);
    u32 i;
    if (seam == NULL)
        return;
    // LoadBgTiles queues after the original full tileset copies; never race a
    // synchronous VRAM overwrite against a pending original tileset DMA.
    for (i = 0; i < seam->glyphRunCount; i++)
        LoadBgTiles(2, seam->glyphRuns[i].pixels, seam->glyphRuns[i].size, seam->glyphRuns[i].destination);
    for (i = 0; i < seam->paletteCount; i++)
        if (skipFaded)
            CpuCopy16(seam->palettes[i].colors, &gPlttBufferUnfaded[seam->palettes[i].destination], PLTT_SIZE_4BPP);
        else
            LoadPaletteFast(seam->palettes[i].colors, seam->palettes[i].destination, PLTT_SIZE_4BPP);
}
